package org.delcom.ifs25019springbootcashflow.usecase;
import org.springframework.stereotype.Service; import org.delcom.ifs25019springbootcashflow.domain.*; import org.delcom.ifs25019springbootcashflow.domain.repository.*; import java.util.*;
@Service public class UserUseCase {private final IUserRepository repo; public UserUseCase(IUserRepository r){repo=r;} public List<User> list(){return repo.findAll();} public User get(long id)throws DomainException{return repo.findById(id).orElseThrow(()->new EntityNotFoundException("Pengguna tidak ditemukan."));} public User updateName(User u,String name)throws DomainException{if(name==null||name.isBlank())throw new ValidationException("Nama tidak boleh kosong.");return repo.save(new User(u.id(),u.username(),u.passwordHash(),name,u.role(),u.photoPath()));} public User updatePhoto(User u,String photoPath){return repo.save(new User(u.id(),u.username(),u.passwordHash(),u.fullName(),u.role(),photoPath));} public User updatePassword(User u,String pass)throws DomainException{if(pass==null||pass.length()<6)throw new ValidationException("Password minimal 6 karakter.");return repo.save(new User(u.id(),u.username(),PasswordHasher.hash(pass),u.fullName(),u.role(),u.photoPath()));}}
